def object_for(lid):
    for rx, key in R:
        if rx.search(lid):
            return MERGE.get(key, key)
    return None


def main():
    t = open(os.path.join(ROOT, "wordbank", "words.js"), encoding="utf-8").read()
    lessons = json.loads(t[t.index("{"): t.rindex("}") + 1])["lessons"]
    mp, miss, bad = {}, [], set()
    for l in lessons:
        k = object_for(l["id"])
        if k is None: miss.append(l["id"]); continue
        if k not in KEYS: bad.add(k); continue
        mp[l["id"]] = k
    used = set(mp.values())
    print("library", len(KEYS), "| lessons", len(lessons), "| mapped", len(mp))
    print("unmapped:", miss)
    print("bad keys:", sorted(bad))
    print("unused objects:", [k for k in KEYS if k not in used])
    if miss or bad:
        return
    per = 36
    lib = [{"key": k, "name": d, "sheet": i // per + 1, "cell": i % per} for i, (k, d) in enumerate(LIB)]
    json.dump({"cols": 6, "rows": 6, "library": lib, "map": mp}, open(os.path.join(ROOT, "journey", "objects.json"), "w"), indent=1)
    out = ["# My Room: painted object sheets", "",
           "%d objects on %d sheets, 36 per sheet (6 columns by 6 rows). Each lesson in My Room gets the object that matches its title." % (len(LIB), (len(LIB) + per - 1) // per), "",
           "How to use, once per sheet:",
           "1. In ChatGPT, attach one room picture (the Study is best) so it copies the painting style, then paste the sheet prompt.",
           "2. If the count or order is wrong, say: \"Exactly 36 objects, 6 columns by 6 rows, in the order listed, each fully separate with magenta all round it.\" If ChatGPT struggles with 36, ask for the first 18 and then the last 18 as two images and tell me.",
           "3. Save each result as `journey/img/sheet01.png` ... `sheet10.png` (or just send them to me). Tell me which sheet number each is.", ""]
    for n in range((len(LIB) + per - 1) // per):
        chunk = LIB[n * per:(n + 1) * per]
        rows = []
        for ri in range(0, len(chunk), 6):
            rows.append("Row %d: " % (ri // 6 + 1) + "; ".join(d for _, d in chunk[ri:ri + 6]) + ".")
        out += ["---", "", "## Sheet %02d" % (n + 1), "", "```",
                "[Attached: one of my painted room images. Use it only as the reference for painting style, lighting and colour richness.]", "",
                "A masterpiece-quality painted collection sheet of EXACTLY %d small treasures, arranged in a perfect grid of 6 columns by 6 rows, every object fully separate with generous empty space around it. The background is perfectly flat, pure magenta (#FF00FF) with no gradient, texture or shadows, so the objects can be cut out cleanly. Do not use magenta or pink anywhere in the objects." % len(chunk), "",
                "Style: the same near-photorealistic painterly rendering as the attached room, like collectible museum pieces: rich oil-paint texture, warm golden light from the upper left, soft shading on the object itself, jewel-like colour. Each object is seen from the same slightly raised three-quarter angle, centred in its cell, about the same visual size, fully inside its cell, with a crisp clean edge. No cast shadows on the background, no text, no letters, no numbers, no people, no frames, no labels, no watermarks.", "",
                "The objects, left to right, top to bottom:"] + rows + ["", "Every object is complete, crisp-edged and clearly separate. Square image, 2048 x 2048 or larger.", "```", ""]
    open(os.path.join(ROOT, "JOURNEY_OBJECT_SHEETS.md"), "w", encoding="utf-8").write("\n".join(out))
    print("wrote objects.json and JOURNEY_OBJECT_SHEETS.md")

if __name__ == "__main__":
    main()
